style.css:
@-moz-document domain("youtube.com") {
/* Set the main website background to the strawberry milk image */
    html, 
    body, 
    ytd-app, 
    #page-manager.ytd-app,
    ytd-browse, 
    ytd-watch-flexy,
    #columns.ytd-watch-flexy {
        background: url("https://pinimg.com") center center / cover no-repeat fixed !important;
    }

    /* Make content containers transparent so the background shows through */
    #contentContainer.app-header-layout,
    #page-manager,
    ytd-masthead,
    #container.ytd-masthead,
    #guide-content.ytd-app,
    ytd-mini-guide-renderer,
    #content-container.ytd-playlist-video-list-renderer,
    #primary.ytd-watch-flexy, 
    #secondary.ytd-watch-flexy,
    ytd-rich-grid-renderer {
        background: transparent !important;
    }

    /* Optional: Add a subtle dark or light translucent tint over elements to keep text readable */
    ytd-rich-item-renderer, 
    ytd-video-renderer, 
    ytd-compact-video-renderer,
    #watch-card_0 {
        background: rgba(255, 255, 255, 0.15) !important;
        padding: 10px !important;
        border-radius: 12px !important;
    }
}
